import { api, esc } from '../core/api.js?v=16.117.0';
import {downloadEncryptedDaftarZip,previewEncryptedDaftarZip} from './daftar-portability.js?v=16.117.0';

const DB_NAME='onmission-daftar-offline-v1';
const CONFIG_KEY='onmission-daftar-offline-config-v1';
let current=null;let scopedDbName=null;let deferredInstallPrompt=null;
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferredInstallPrompt=event;document.querySelector('#dfInstall')?.removeAttribute('hidden');});

export async function renderDaftarWorkspace(el,session){
  el.innerHTML=`<section class="df-hero"><div><span class="df-kicker">AFGHANISTAN · DIGITAL DAAFTAR</span><h1>Give & Get</h1><p>A simple private record of trade, stock, credit and work. Your entries belong to your organization.</p></div><div class="df-status"><span id="dfOnline" class="df-pill">CHECKING CONNECTION</span><span id="dfQueueCount" class="df-pill">0 OFFLINE</span><select id="dfLocale" aria-label="Language"><option value="en">English</option><option value="prs-AF">دری</option><option value="ps-AF">پښتو</option></select><span id="dfLocaleNote" class="df-locale-note" hidden>Beta translation · native-speaker and legal review required</span><button type="button" id="dfInstall" class="df-button df-button-light" hidden>INSTALL APP</button></div></section><div id="dfNotice" class="df-notice" role="status">Loading your market and sector configuration…</div><div id="dfWorkspace"></div>`;
  const notice=el.querySelector('#dfNotice'),surface=el.querySelector('#dfWorkspace');
  const updateNetwork=async()=>{const online=navigator.onLine;el.querySelector('#dfOnline').textContent=online?'ONLINE':'OFFLINE · CAPTURE ENABLED';el.querySelector('#dfOnline').classList.toggle('offline',!online);try{const q=await readQueue();el.querySelector('#dfQueueCount').textContent=`${q.length} QUEUED`;renderOfflineQueue(el.querySelector('#dfOfflineQueue'),q,notice,updateNetwork);applyDaftarLocale(document.querySelector('#dfWorkspace')?.parentElement||el,document.querySelector('#dfLocale')?.value||'en');}catch{el.querySelector('#dfQueueCount').textContent='OFFLINE STORAGE UNAVAILABLE';}};
  window.addEventListener('online',async()=>{await updateNetwork();if(!scopedDbName)return;try{const fresh=await api('/api/v1/daftar/bootstrap');const nextScope=`${DB_NAME}:${fresh.offlineScope}`;if(nextScope!==scopedDbName){current=fresh;scopedDbName=nextScope;cacheOfflineConfig(fresh);notice.textContent='Account context changed. Previous offline entries remain isolated in their original device workspace and were not sent under this account.';await updateNetwork();return;}current=fresh;cacheOfflineConfig(fresh);await syncQueue(notice,updateNetwork);await refreshWorkspace(el,notice,updateNetwork);}catch(error){notice.textContent=`Connection restored, but the account context could not be verified. Offline entries were not synchronized. ${error.message||''}`;}});window.addEventListener('offline',updateNetwork);
  try{
    if('serviceWorker' in navigator) navigator.serviceWorker.register('/daftar-sw.js',{scope:'/'}).catch(()=>{});
    current=await api('/api/v1/daftar/bootstrap');
    scopedDbName=`${DB_NAME}:${current.offlineScope}`;
    cacheOfflineConfig(current);
    renderDashboard(surface,current,notice,updateNetwork);
    await updateNetwork();
    if(navigator.onLine) await syncQueue(notice,updateNetwork).catch(error=>{notice.textContent=`Saved on this device. Sync will retry when the connection is stable. ${error.message||''}`;});
  }catch(error){
    const cached=loadOfflineConfig();
    if(!navigator.onLine&&cached?.offlineScope&&cached?.template){current=cached;scopedDbName=`${DB_NAME}:${cached.offlineScope}`;renderDashboard(surface,{...cached,summary:{entryCount:0,reportedSalesByCurrency:[],qarzReceivableByCurrency:[],qarzPayableByCurrency:[],qarzOutstandingByCurrency:[],openReceivableEntries:0,openPayableEntries:0,openCreditEntries:0},inventory:[],recentEntries:[]},notice,updateNetwork);notice.textContent='Offline mode: this device is using its last cached country/sector template. New records stay encrypted on this device until the same account reconnects.';await updateNetwork();return;}
    surface.innerHTML=`<section class="df-panel"><h2>Daftar is not enabled for this account yet</h2><p>${esc(error.message||'Market configuration is unavailable.')}</p><p class="df-muted">The Afghanistan product market must be activated and this organization must have an enabled country/sector template. No separate account or backend is created for Daftar.</p><a class="df-button" href="#account">OPEN ACCOUNT</a></section>`;
    notice.textContent='Market access is governed by your existing ON Mission account and country/sector configuration.';
  }
}

function renderDashboard(el,data,notice,updateNetwork){
  const template=data.template||{};const sector=data.sector||{};const types=(sector.entryTypes||[]).map(code=>({code,...(template.entryTypes||{})[code]}));
  const units=(template.units?.canonical||[]).map(x=>`<option value="${esc(x.code)}">${esc(x.label)} (${esc(x.code)})</option>`).join('')+`<option value="seer">Seer · requires local approval</option><option value="man">Man · requires local approval</option>`;
  const currencies=(template.supportedCurrencies||['AFN']).map(x=>`<option value="${esc(x)}" ${x==='AFN'?'selected':''}>${esc(x)}</option>`).join('');
  const methods=(template.paymentMethods||[]).map(x=>`<option value="${esc(x)}">${esc(x.replaceAll('_',' '))}</option>`).join('');
  const entries=types.map(x=>`<option value="${esc(x.code)}">${esc(x.label||x.code)}</option>`).join('');
  el.innerHTML=`
    <section class="df-stats"><article><span>ENTRIES · 30 DAYS</span><strong>${Number(data.summary?.entryCount||0)}</strong></article><article><span>REPORTED SALES</span><strong>${(data.summary?.reportedSalesByCurrency||[]).map(x=>money(x.amountMinor,x.currencyCode)).join(' · ')||money(0,'AFN')}</strong><small>Self-reported, not independently verified</small></article><article><span>QARZ · TO RECEIVE</span><strong>${(data.summary?.qarzReceivableByCurrency||[]).map(x=>money(x.amountMinor,x.currencyCode)).join(' · ')||money(0,'AFN')}</strong><small>${Number(data.summary?.openReceivableEntries||0)} receivable records</small></article><article><span>QARZ · TO PAY</span><strong>${(data.summary?.qarzPayableByCurrency||[]).map(x=>money(x.amountMinor,x.currencyCode)).join(' · ')||money(0,'AFN')}</strong><small>${Number(data.summary?.openPayableEntries||0)} payable records</small></article></section>
    <div class="df-grid"><section class="df-panel df-entry-panel"><div class="df-section-head"><div><span class="df-kicker">QUICK ENTRY</span><h2>Record a give or get</h2><p>Save now; synchronize when a connection is available.</p></div><span class="df-tag">${esc(sector.label||data.market?.sectorCode||'Daftar')}</span></div>
      <form id="dfEntryForm" class="df-form"><label>Entry type<select id="dfEntryType" required>${entries}</select></label><label>Direction<select id="dfDirection"><option value="give">I gave / supplied</option><option value="get">I received / bought</option></select></label><div class="df-row"><label>Item / service code<input id="dfItem" maxlength="80" placeholder="e.g. cumin, wheat, freight"></label><label>City code<input id="dfCity" maxlength="32" placeholder="e.g. HERAT"></label></div><div id="dfFreightWrap" class="df-hidden"><div class="df-row"><label>Origin code<input id="dfOrigin" maxlength="80" placeholder="Origin"></label><label>Destination code<input id="dfDestination" maxlength="80" placeholder="Destination"></label></div><label>Waybill / reference code<input id="dfReference" maxlength="80" placeholder="Optional waybill reference"></label></div><div class="df-row"><label>Quantity<input id="dfQuantity" type="number" min="0.001" step="0.001" required placeholder="0.000"></label><label>Unit<select id="dfUnit">${units}</select></label></div><div class="df-row"><label>Unit price <small>(optional calculator)</small><input id="dfUnitPrice" type="number" min="0.01" step="0.01" placeholder="0.00"></label><label>Amount<input id="dfAmount" type="number" min="0.01" step="0.01" required placeholder="0.00"></label></div><label>Currency<select id="dfCurrency">${currencies}</select></label><div id="dfFxWrap" class="df-hidden"><div class="df-row"><label>Received amount<input id="dfCounterAmount" type="number" min="0.01" step="0.01"></label><label>Received currency<select id="dfCounterCurrency">${currencies}</select></label></div><label>Exchange-rate source / note<input id="dfFxSource" maxlength="80" placeholder="Merchant-reported rate source"></label></div><div class="df-row"><label>Payment method<select id="dfPayment">${methods}</select></label><label>Counterparty label <small>(private)</small><input id="dfCounterparty" maxlength="120" placeholder="Optional name or label"></label></div><label id="dfRelatedWrap" class="df-hidden">Qarz entry ID<input id="dfRelated" maxlength="128" placeholder="Original credit entry ID"></label><div class="df-callout">Wallet and Hawala references are recorded as reported payment methods only. ON Mission does not verify a payment from a typed reference or move money. Do not enter phone numbers, national IDs or sensitive customer details in labels.</div><button class="df-button" type="submit">SAVE ENTRY</button><span id="dfSaveState" class="df-muted"></span></form></section>
      <section class="df-panel"><div class="df-section-head"><div><span class="df-kicker">YOUR RECORDS</span><h2>Recent ledger</h2><p>Visible only to your organization.</p></div><button class="df-button df-button-light" id="dfRefresh">REFRESH</button></div><div id="dfLedger" class="df-list">${renderEntries(data.recentEntries||[])}</div></section>
      <section class="df-panel"><div class="df-section-head"><div><span class="df-kicker">STOCK</span><h2>Mojoodi</h2><p>Inventory updates only when the quantity has an approved canonical unit conversion.</p></div></div><div id="dfStock" class="df-list">${renderStock(data.inventory||[])}</div></section>
      <section class="df-panel"><div class="df-section-head"><div><span class="df-kicker">MARKET TELEMETRY</span><h2>Local price signals</h2><p>Published only after enough independent businesses contribute.</p></div></div><div id="dfMarket" class="df-list"><p class="df-muted">Loading aggregate market feed…</p></div><label class="df-consent"><input id="dfTelemetryConsent" type="checkbox" ${data.privacy?.telemetryOptIn?'checked':''} ${!data.privacy?.telemetryEnabled?'disabled':''}><span><b>Share minimized market insights</b><small>Optional. Your names, customer details, notes and private ledger are not shared. A pseudonymous merchant key is used to prevent one merchant from counting as many contributors. You can withdraw consent.</small></span></label><button class="df-button df-button-light" id="dfSaveConsent" ${!data.privacy?.telemetryEnabled?'disabled':''}>SAVE PRIVACY CHOICE</button></section>
      <section class="df-panel"><div class="df-section-head"><div><span class="df-kicker">PRODUCT PASSPORTS</span><h2>Batch traceability</h2><p>Record provenance and custody evidence. Public QR views show only selected fields.</p></div></div><form id="dfPassportForm" class="df-form"><div class="df-row"><label>Product code<input id="dfProductCode" required maxlength="80" placeholder="e.g. saffron"></label><label>Batch code<input id="dfBatchCode" required maxlength="80" placeholder="e.g. HER-2026-001"></label></div><div class="df-row"><label>Quantity<input id="dfPassportQty" required type="number" min="0.001" step="0.001"></label><label>Unit<select id="dfPassportUnit">${units}</select></label></div><label class="df-checkbox"><input id="dfPassportPublic" type="checkbox"><span>Make the passport publicly verifiable (selected product/batch facts and event dates only).</span></label><button class="df-button" type="submit">CREATE BATCH PASSPORT</button><div id="dfPassportResult" class="df-muted"></div></form><div id="dfPassports" class="df-list"></div><div class="df-transfer-tools"><h3>Custody handoff</h3><p class="df-muted">Create a one-time QR-ready challenge for the receiving organization. Only an authenticated account belonging to that recipient can confirm it.</p><form id="dfTransferForm" class="df-form"><label>Passport ID<input id="dfTransferPassport" required maxlength="64" placeholder="Batch passport ID"></label><label>Receiving organization ID<input id="dfTransferTenant" type="number" min="1" required></label><button class="df-button df-button-light" type="submit">CREATE HANDOFF CHALLENGE</button><div id="dfTransferResult" class="df-muted"></div></form><form id="dfConfirmTransferForm" class="df-form"><label>Transfer ID<input id="dfConfirmTransferId" required maxlength="64"></label><label>One-time challenge token<input id="dfConfirmTransferToken" required maxlength="128"></label><button class="df-button" type="submit">CONFIRM AS RECEIVER</button><div id="dfConfirmTransferResult" class="df-muted"></div></form></div></section>
    </div>`;
  el.insertAdjacentHTML('beforeend',`<section class="df-panel df-book-panel"><div class="df-section-head"><div><span class="df-kicker">BUSINESS BOOK</span><h2>Daily business book</h2><p>Balanced, single-currency journal entries generated with the private operational record.</p></div><span id="dfBookBalance" class="df-tag">Checking reconciliation…</span></div><div id="dfBookSummary" class="df-list">Loading journal balances…</div><div class="df-row"><a class="df-button df-button-light" href="/api/v1/daftar/export?format=csv">DOWNLOAD CSV</a><button type="button" id="dfDownloadJson" class="df-button df-button-light">DOWNLOAD JSON</button><button type="button" id="dfPrintPdf" class="df-button df-button-light">PRINT / SAVE PDF</button></div><div class="df-notice-inline">Downloads and receipts contain private organization records. Store exported files securely and share them only with authorized recipients.</div><div class="df-transfer-tools"><h3>Encrypted organization backup</h3><p class="df-muted">Creates a ZIP containing AES-256-GCM encrypted business data. Keep the password separately. Restore currently validates a backup preview; it does not import or overwrite live records.</p><div class="df-row"><label>Backup password<input id="dfBackupPassword" type="password" minlength="12" autocomplete="new-password" placeholder="At least 12 characters"></label><button type="button" id="dfCreateBackup" class="df-button">CREATE ENCRYPTED ZIP</button></div><form id="dfBackupPreviewForm" class="df-form"><label>Choose backup ZIP<input id="dfBackupFile" type="file" accept=".zip,application/zip" required></label><label>Password<input id="dfRestorePassword" type="password" autocomplete="current-password" required></label><button class="df-button df-button-light" type="submit">VALIDATE BACKUP</button><div id="dfBackupResult" class="df-muted" role="status"></div></form></div><div class="df-notice-inline">Financial and payment entries are merchant-reported unless an approved external provider independently confirms them. This operational book is not a certification of statutory accounting or tax compliance.</div></section><section class="df-panel df-book-panel"><div class="df-section-head"><div><span class="df-kicker">OFFLINE RECOVERY</span><h2>Device sync queue</h2><p>Encrypted entries stay scoped to the original account and identity. Rejected entries stay on this device until retried or explicitly removed. Review the error and re-enter a corrected record if needed.</p></div><button type="button" id="dfRetryQueue" class="df-button df-button-light">RETRY SYNC</button></div><div id="dfOfflineQueue" class="df-list">Loading device queue…</div></section>`);
  const typeSelect=el.querySelector('#dfEntryType'),direction=el.querySelector('#dfDirection'),related=el.querySelector('#dfRelatedWrap');
  const updateType=()=>{const type=typeSelect.value;const allowed=template.entryTypes?.[type]?.directions||['give','get'];direction.innerHTML=allowed.map(x=>`<option value="${x}">${x==='give'?'I gave / supplied':'I received / bought'}</option>`).join('');related.classList.toggle('df-hidden',type!=='credit_settlement');el.querySelector('#dfRelated').required=type==='credit_settlement';el.querySelector('#dfFxWrap').classList.toggle('df-hidden',type!=='fx_exchange');el.querySelector('#dfFreightWrap').classList.toggle('df-hidden',type!=='freight'||current.market?.sectorCode!=='logistics');el.querySelector('#dfOrigin').required=type==='freight'&&current.market?.sectorCode==='logistics';el.querySelector('#dfDestination').required=type==='freight'&&current.market?.sectorCode==='logistics';el.querySelector('#dfCounterAmount').required=type==='fx_exchange';el.querySelector('#dfItem').required=['sale','purchase'].includes(type);el.querySelector('#dfQuantity').required=['sale','purchase','freight','wage'].includes(type);};typeSelect.addEventListener('change',updateType);updateType();const updateFxPair=()=>{const base=el.querySelector('#dfCurrency').value,counter=el.querySelector('#dfCounterCurrency');if(counter.value===base)counter.value=(template.supportedCurrencies||[]).find(x=>x!==base)||base;};el.querySelector('#dfCurrency').addEventListener('change',updateFxPair);updateFxPair();const recalc=()=>{const q=Number(el.querySelector('#dfQuantity').value),p=Number(el.querySelector('#dfUnitPrice').value);if(q>0&&p>0)el.querySelector('#dfAmount').value=(q*p).toFixed(2);};el.querySelector('#dfQuantity').addEventListener('input',recalc);el.querySelector('#dfUnitPrice').addEventListener('input',recalc);
  el.querySelector('#dfEntryForm').addEventListener('submit',async e=>{e.preventDefault();const state=el.querySelector('#dfSaveState');const type=typeSelect.value;const id=crypto.randomUUID();const payload={clientEntryId:id,idempotencyKey:crypto.randomUUID(),entryType:type,direction:direction.value,itemCode:el.querySelector('#dfItem').value.trim(),cityCode:el.querySelector('#dfCity').value.trim(),originCode:el.querySelector('#dfOrigin').value.trim()||null,destinationCode:el.querySelector('#dfDestination').value.trim()||null,referenceCode:el.querySelector('#dfReference').value.trim()||null,quantity:el.querySelector('#dfQuantity').value||null,unitCode:el.querySelector('#dfUnit').value,amount:el.querySelector('#dfAmount').value,currencyCode:el.querySelector('#dfCurrency').value,paymentMethod:el.querySelector('#dfPayment').value,counterAmount:el.querySelector('#dfCounterAmount').value||null,counterCurrencyCode:el.querySelector('#dfCounterCurrency').value,exchangeRateSource:el.querySelector('#dfFxSource').value||'merchant_reported',counterpartyLabel:el.querySelector('#dfCounterparty').value.trim()||null,relatedEntryId:el.querySelector('#dfRelated').value.trim()||null,recordedAt:new Date().toISOString()};try{await enqueue(payload);state.textContent='Saved encrypted on this device.';e.target.reset();updateType();await updateNetwork();if(navigator.onLine){await syncQueue(state,updateNetwork).catch(error=>{state.textContent=`Saved locally; sync will retry. ${error.message||''}`;});await refreshWorkspace(el,state,updateNetwork).catch(error=>{state.textContent=`Saved locally; server refresh will retry. ${error.message||''}`;});}else{state.textContent='Saved encrypted offline. Keep this account session and device available; synchronization will occur when connectivity returns.';notice.textContent='Offline capture is active. Entries are encrypted and scoped to this account and identity.';}}catch(error){state.textContent=error.message||'Could not save this entry locally.';}});
  el.querySelector('#dfRefresh').onclick=()=>refreshWorkspace(el,notice,updateNetwork);
  const localeSelect=document.querySelector('#dfLocale');if(localeSelect)localeSelect.onchange=e=>applyDaftarLocale(document.querySelector('#dfWorkspace')?.parentElement||el,e.target.value);
  el.querySelector('#dfPrintPdf').onclick=async()=>{const win=window.open('about:blank','_blank');if(!win){notice.textContent='Allow pop-ups to print or save your Daftar statement as PDF.';return;}try{const d=await api('/api/v1/daftar/book/summary');const escHtml=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const moneyHtml=(v,c)=>escHtml(money(v,c));const accounts=(d.accounts||[]).map(x=>`<tr><td>${escHtml(x.accountCode)}</td><td>${escHtml(x.currencyCode)}</td><td>${moneyHtml(x.debitMinor,x.currencyCode)}</td><td>${moneyHtml(x.creditMinor,x.currencyCode)}</td></tr>`).join('');const reports=(d.dailyReports||[]).map(x=>`<tr><td>${escHtml(x.day)}</td><td>${escHtml(x.currency_code)}</td><td>${moneyHtml(x.income_minor,x.currency_code)}</td><td>${moneyHtml(x.purchases_minor,x.currency_code)}</td><td>${moneyHtml(x.expenses_minor,x.currency_code)}</td></tr>`).join('');const recent=(d.recent||[]).slice(0,50).map(x=>`<tr><td>${escHtml(x.created_at)}</td><td>${escHtml(x.transaction_type)}</td><td>${escHtml(x.currency_code)}</td><td>${moneyHtml(x.amount_minor,x.currency_code)}</td><td>${escHtml(x.payment_evidence_class)}</td></tr>`).join('');win.document.open();win.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>ON Mission Daftar Statement</title><style>body{font:13px Arial,sans-serif;color:#17263a;margin:28px}h1{font-size:22px}h2{font-size:15px;margin:24px 0 8px}p{color:#536174}table{width:100%;border-collapse:collapse;margin:8px 0 18px}th,td{text-align:left;padding:7px;border-bottom:1px solid #dbe2ea;font-size:11px}th{background:#f2f5f8}.notice{padding:10px;background:#f2f5f8;border-radius:6px;margin:12px 0}@media print{body{margin:12mm}a{display:none}}</style></head><body><h1>ON Mission · Digital Daftar</h1><p>Business book statement · ${escHtml(current.market.countryCode)} / ${escHtml(current.market.sectorCode)} · ${new Date().toLocaleString()}</p><div class="notice">${d.reconciliation?.balanced?'Journal debit and credit totals reconcile within each currency.':'Reconciliation requires review.'} All payment confirmations are merchant-reported unless independently provider-verified.</div><h2>Account balances</h2><table><thead><tr><th>Account</th><th>Currency</th><th>Debits</th><th>Credits</th></tr></thead><tbody>${accounts||'<tr><td colspan="4">No journal entries</td></tr>'}</tbody></table><h2>Last 30 days</h2><table><thead><tr><th>Date</th><th>Currency</th><th>Income</th><th>Purchases</th><th>Expenses</th></tr></thead><tbody>${reports||'<tr><td colspan="5">No daily activity</td></tr>'}</tbody></table><h2>Recent transactions</h2><table><thead><tr><th>Date</th><th>Type</th><th>Currency</th><th>Amount</th><th>Evidence class</th></tr></thead><tbody>${recent||'<tr><td colspan="5">No transactions</td></tr>'}</tbody></table><p>Private organization statement. This report is an operational record and is not a statutory tax or accounting certification.</p><script>window.onload=()=>window.print()<\/script></body></html>`);win.document.close();}catch(error){win.close();notice.textContent=error.message||'PDF print view unavailable.';}};
  el.querySelector('#dfDownloadJson').onclick=async()=>{if(!confirm('This export contains private organization records. Download only to a device you control?'))return;try{const response=await fetch('/api/v1/daftar/export?format=json',{credentials:'same-origin'});if(!response.ok)throw new Error('JSON export unavailable');const blob=await response.blob();downloadBlob(blob,`onmission-daftar-${current.market.countryCode}.json`);}catch(error){notice.textContent=error.message||'Export unavailable.';}};
  el.querySelector('#dfCreateBackup').onclick=async()=>{const button=el.querySelector('#dfCreateBackup'),password=el.querySelector('#dfBackupPassword').value;if(password.length<12){notice.textContent='Backup password must contain at least 12 characters.';return;}button.disabled=true;try{const response=await fetch('/api/v1/daftar/export?format=json',{credentials:'same-origin'});if(!response.ok)throw new Error('Organization export unavailable');const payload=await response.json();const result=await downloadEncryptedDaftarZip(payload,password);notice.textContent=`Encrypted backup ZIP created (${Math.round(result.size/1024)} KB). Keep the password separately.`;}catch(error){notice.textContent=error.message||'Encrypted backup could not be created.';}finally{button.disabled=false;}};
  el.querySelector('#dfBackupPreviewForm').onsubmit=async e=>{e.preventDefault();const out=el.querySelector('#dfBackupResult');try{const file=el.querySelector('#dfBackupFile').files[0],password=el.querySelector('#dfRestorePassword').value;out.textContent='Decrypting and validating backup…';const result=await previewEncryptedDaftarZip(file,password);out.textContent=`Backup validation ${result.status.toUpperCase()} · ${result.recordCount} records · ${result.previewId}. No live data was changed.`;}catch(error){out.textContent=error.message||'Backup validation failed.';}};
  loadBook(el.querySelector('#dfBookSummary'),el.querySelector('#dfBookBalance'));
  el.querySelector('#dfRetryQueue').onclick=async()=>{try{await syncQueue(notice,updateNetwork);await refreshWorkspace(el,notice,updateNetwork);}catch(error){notice.textContent=error.message||'Queue synchronization failed.';}};
  bindReceiptButtons(el,current);
  const installButton=document.querySelector('#dfInstall');if(installButton){if(deferredInstallPrompt)installButton.hidden=false;installButton.onclick=async()=>{if(!deferredInstallPrompt){notice.textContent='Use your browser menu and choose Install app or Add to Home Screen.';return;}deferredInstallPrompt.prompt();await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;installButton.hidden=true;};}
  let savedLocale='en';try{savedLocale=localStorage.getItem('onmission.daftar.locale')||'en';}catch{}if(localeSelect&&['en','prs-AF','ps-AF'].includes(savedLocale))localeSelect.value=savedLocale;applyDaftarLocale(document.querySelector('#dfWorkspace')?.parentElement||el,localeSelect?.value||'en');
  el.querySelector('#dfSaveConsent').onclick=async()=>{const b=el.querySelector('#dfSaveConsent');b.disabled=true;try{await api('/api/v1/daftar/consent',{method:'POST',body:{telemetryOptIn:el.querySelector('#dfTelemetryConsent').checked}});notice.textContent='Privacy choice saved.';}catch(error){notice.textContent=error.message||'Privacy choice could not be saved.';}finally{b.disabled=false;}};
  el.querySelector('#dfTransferForm').onsubmit=async e=>{e.preventDefault();const out=el.querySelector('#dfTransferResult');try{const passportId=el.querySelector('#dfTransferPassport').value.trim();const result=await api(`/api/v1/daftar/passports/${encodeURIComponent(passportId)}/transfers`,{method:'POST',body:{toCompanyId:Number(el.querySelector('#dfTransferTenant').value)}});const payload=JSON.stringify({transferId:result.transferId,challengeToken:result.challengeToken});out.innerHTML=`Challenge created. Share this payload privately with the receiving organization (valid 30 minutes):<pre>${esc(payload)}</pre><button type="button" class="df-button df-button-light" id="dfCopyTransfer">COPY QR PAYLOAD</button>`;out.querySelector('#dfCopyTransfer').onclick=()=>navigator.clipboard?.writeText(payload);}catch(error){out.textContent=error.message||'Could not create custody challenge.';}};
  el.querySelector('#dfConfirmTransferForm').onsubmit=async e=>{e.preventDefault();const out=el.querySelector('#dfConfirmTransferResult');try{const transferId=el.querySelector('#dfConfirmTransferId').value.trim();const result=await api(`/api/v1/daftar/transfers/${encodeURIComponent(transferId)}/confirm`,{method:'POST',body:{challengeToken:el.querySelector('#dfConfirmTransferToken').value.trim()}});out.textContent=`Custody handoff confirmed for passport ${result.passportId}.`;await loadPassports(el.querySelector('#dfPassports'));}catch(error){out.textContent=error.message||'Custody handoff could not be confirmed.';}};
  el.querySelector('#dfPassportForm').onsubmit=async e=>{e.preventDefault();const out=el.querySelector('#dfPassportResult');try{const result=await api('/api/v1/daftar/passports',{method:'POST',body:{productCode:el.querySelector('#dfProductCode').value,batchCode:el.querySelector('#dfBatchCode').value,quantity:el.querySelector('#dfPassportQty').value,unitCode:el.querySelector('#dfPassportUnit').value,visibility:el.querySelector('#dfPassportPublic').checked?'public':'private'}});out.innerHTML=result.publicToken?`Passport created. Save this one-time QR verification link: <a href="${esc(result.verificationPath)}" target="_blank" rel="noopener">OPEN PUBLIC PASSPORT</a><br><code>${esc(location.origin+result.verificationPath)}</code>`:'Passport created as private.';await refreshWorkspace(el,notice,updateNetwork);}catch(error){out.textContent=error.message||'Passport could not be created.';}};
  if(data.market?.sectorCode==='fx'){
    const fxPanel=document.createElement('section');fxPanel.className='df-panel';
    fxPanel.innerHTML='<div class="df-section-head"><div><span class="df-kicker">REFERENCE ONLY</span><h2>Approved FX quotes</h2><p>Reference quotes do not execute an exchange.</p></div></div><div id="dfFxQuotes" class="df-list">Loading approved quotes…</div><form id="dfFxPreviewForm" class="df-form"><div class="df-row"><label>Amount<input id="dfFxAmount" type="number" min="0.01" step="0.01" required></label><label>From<select id="dfFxBase"><option>AFN</option><option>USD</option><option>EUR</option></select></label></div><label>To<select id="dfFxQuote"><option>USD</option><option>AFN</option><option>EUR</option></select></label><button class="df-button df-button-light" type="submit">PREVIEW CONVERSION</button><div id="dfFxPreviewResult" class="df-muted"></div></form>';
    el.querySelector('.df-grid').insertBefore(fxPanel,el.querySelector('.df-grid').children[4]);
    loadFxQuotes(fxPanel.querySelector('#dfFxQuotes'));
    fxPanel.querySelector('#dfFxPreviewForm').onsubmit=async ev=>{ev.preventDefault();const out=fxPanel.querySelector('#dfFxPreviewResult');try{const preview=await api('/api/v1/daftar/fx/convert-preview',{method:'POST',body:{amount:fxPanel.querySelector('#dfFxAmount').value,baseCurrency:fxPanel.querySelector('#dfFxBase').value,quoteCurrency:fxPanel.querySelector('#dfFxQuote').value}});out.textContent=`Preview: ${money(preview.originalAmountMinor,preview.baseCurrency)} = ${money(preview.convertedAmountMinor,preview.quoteCurrency)} · ${preview.sourceCode} · expires ${preview.validUntil}`;}catch(error){out.textContent=error.message||'No approved FX quote.';}};
  }
  loadMarket(el.querySelector('#dfMarket'));loadPassports(el.querySelector('#dfPassports'));
}

async function refreshWorkspace(el,notice,updateNetwork){try{const d=await api('/api/v1/daftar/bootstrap');current=d;scopedDbName=`${DB_NAME}:${d.offlineScope}`;cacheOfflineConfig(d);el.querySelector('.df-stats').innerHTML=`<article><span>ENTRIES · 30 DAYS</span><strong>${Number(d.summary?.entryCount||0)}</strong></article><article><span>REPORTED SALES</span><strong>${(d.summary?.reportedSalesByCurrency||[]).map(x=>money(x.amountMinor,x.currencyCode)).join(' · ')||money(0,'AFN')}</strong><small>Self-reported</small></article><article><span>QARZ · TO RECEIVE</span><strong>${(d.summary?.qarzReceivableByCurrency||[]).map(x=>money(x.amountMinor,x.currencyCode)).join(' · ')||money(0,'AFN')}</strong><small>${Number(d.summary?.openReceivableEntries||0)} receivable records</small></article><article><span>QARZ · TO PAY</span><strong>${(d.summary?.qarzPayableByCurrency||[]).map(x=>money(x.amountMinor,x.currencyCode)).join(' · ')||money(0,'AFN')}</strong><small>${Number(d.summary?.openPayableEntries||0)} payable records</small></article>`;el.querySelector('#dfLedger').innerHTML=renderEntries(d.recentEntries||[]);bindReceiptButtons(el,d);el.querySelector('#dfStock').innerHTML=renderStock(d.inventory||[]);await loadMarket(el.querySelector('#dfMarket'));await loadPassports(el.querySelector('#dfPassports'));await loadBook(el.querySelector('#dfBookSummary'),el.querySelector('#dfBookBalance'));await updateNetwork();applyDaftarLocale(document.querySelector('#dfWorkspace')?.parentElement||el,document.querySelector('#dfLocale')?.value||'en');}catch(error){notice.textContent=error.message||'Could not refresh Daftar.';}}
async function loadBook(el,balance){if(!el)return;try{const d=await api('/api/v1/daftar/book/summary');const currencies=d.currencies||[];balance.textContent=d.reconciliation?.balanced?'BALANCED':'CHECK REQUIRED';balance.classList.toggle('df-tag-warn',!d.reconciliation?.balanced);const accounts=(d.accounts||[]).map(x=>`<div class="df-list-row"><span><b>${esc(x.accountCode.replaceAll('_',' '))}</b><small>${esc(x.currencyCode)} · debit ${money(x.debitMinor,x.currencyCode)} · credit ${money(x.creditMinor,x.currencyCode)}</small></span><strong>${money(Math.abs(x.balanceMinor),x.currencyCode)} ${x.balanceMinor<0?'CR':'DR'}</strong></div>`).join('');const reports=(d.dailyReports||[]).map(x=>`<div class="df-list-row"><span><b>${esc(x.day)} · ${esc(x.currency_code)}</b><small>Income ${money(x.income_minor,x.currency_code)} · Purchases ${money(x.purchases_minor,x.currency_code)} · Expenses ${money(x.expenses_minor,x.currency_code)}</small></span><strong>Cash ${money(x.cash_in_minor,x.currency_code)} / ${money(x.cash_out_minor,x.currency_code)}</strong></div>`).join('');el.innerHTML=`<div class="df-subheading">ACCOUNT BALANCES</div>${accounts||'<p class="df-muted">No posted business transactions yet. Sales, purchases, expenses, service and credit settlements create balanced journal pairs.</p>'}<div class="df-subheading">LAST 30 DAYS</div>${reports||'<p class="df-muted">Daily summaries appear after transactions are recorded.</p>'}`;if(currencies.some(x=>!x.balanced))balance.textContent='RECONCILIATION ERROR';applyDaftarLocale(document.querySelector('#dfWorkspace')?.parentElement||el.parentElement,document.querySelector('#dfLocale')?.value||'en');}catch(error){balance.textContent='BOOK UNAVAILABLE';el.textContent=error.message||'Journal data unavailable.';}}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
